using System.Reflection;
using Microsoft.EntityFrameworkCore;
using Wintech.Hrms.Api.Domain.Audit;
using Wintech.Hrms.Api.Domain.Approvals;
using Wintech.Hrms.Api.Domain.Employees;
using Wintech.Hrms.Api.Domain.Identity;
using Wintech.Hrms.Api.Domain.Organization;

namespace Wintech.Hrms.Api.Data;

/// <summary>
/// System of record for HRMS transactions (SQL Server in production, SQLite for local dev/tests).
/// <para>
/// Feature modules DO NOT edit this file: any class under a <c>Wintech.Hrms.Api.Domain.*</c>
/// namespace that has a public <c>Id</c> property is auto-discovered as an entity, and every
/// <c>IEntityTypeConfiguration&lt;T&gt;</c> in the assembly is applied automatically.
/// Query module entities with <c>_db.Set&lt;T&gt;()</c>.
/// </para>
/// </summary>
public class AppDbContext : DbContext
{
    public AppDbContext(DbContextOptions<AppDbContext> options) : base(options)
    {
    }

    // ---- Foundation entities (owned by the core; feature modules use Set<T>() for theirs) ----
    public DbSet<Organization> Organizations => Set<Organization>();
    public DbSet<OrgUnit> OrgUnits => Set<OrgUnit>();
    public DbSet<Location> Locations => Set<Location>();
    public DbSet<Designation> Designations => Set<Designation>();
    public DbSet<Employee> Employees => Set<Employee>();
    public DbSet<EmployeePersonalDetail> EmployeePersonalDetails => Set<EmployeePersonalDetail>();
    public DbSet<EmployeeSensitiveData> EmployeeSensitiveDataSet => Set<EmployeeSensitiveData>();
    public DbSet<EmploymentHistory> EmploymentHistories => Set<EmploymentHistory>();
    public DbSet<ProfileChangeRequest> ProfileChangeRequests => Set<ProfileChangeRequest>();
    public DbSet<UserAccount> UserAccounts => Set<UserAccount>();
    public DbSet<Role> Roles => Set<Role>();
    public DbSet<UserRole> UserRoles => Set<UserRole>();
    public DbSet<RolePermission> RolePermissions => Set<RolePermission>();
    public DbSet<RefreshToken> RefreshTokens => Set<RefreshToken>();
    public DbSet<PasswordResetToken> PasswordResetTokens => Set<PasswordResetToken>();
    public DbSet<AuditEvent> AuditEvents => Set<AuditEvent>();
    public DbSet<ApprovalWorkflowDefinition> ApprovalWorkflowDefinitions => Set<ApprovalWorkflowDefinition>();
    public DbSet<ApprovalWorkflowStep> ApprovalWorkflowSteps => Set<ApprovalWorkflowStep>();
    public DbSet<ApprovalTask> ApprovalTasks => Set<ApprovalTask>();
    public DbSet<ApprovalAction> ApprovalActions => Set<ApprovalAction>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        base.OnModelCreating(modelBuilder);

        // The Render demo shares the workspace's existing free Postgres database; keep all HRMS
        // tables isolated from other applications in their own schema.
        if (string.Equals(Database.ProviderName, "Npgsql.EntityFrameworkCore.PostgreSQL", StringComparison.Ordinal))
            modelBuilder.HasDefaultSchema("wintech_hrms");

        // 1) Auto-discover feature-module entities so modules can grow without touching this file.
        var domainEntities = typeof(AppDbContext).Assembly.GetTypes()
            .Where(t => t.IsClass && !t.IsAbstract && !t.IsGenericTypeDefinition && !t.IsAbstract)
            .Where(t => t.Namespace is not null &&
                        t.Namespace.StartsWith("Wintech.Hrms.Api.Domain", StringComparison.Ordinal))
            .Where(t => t.GetProperty("Id", BindingFlags.Public | BindingFlags.Instance) is not null);

        foreach (var type in domainEntities)
        {
            modelBuilder.Entity(type);
        }

        // 2) Explicit configuration (keys, indexes, relations, delete behaviour) — core + module configs.
        modelBuilder.ApplyConfigurationsFromAssembly(typeof(AppDbContext).Assembly);
    }

    public override int SaveChanges(bool acceptAllChangesOnSuccess)
    {
        PrepareChanges();
        return base.SaveChanges(acceptAllChangesOnSuccess);
    }

    public override Task<int> SaveChangesAsync(bool acceptAllChangesOnSuccess, CancellationToken cancellationToken = default)
    {
        PrepareChanges();
        return base.SaveChangesAsync(acceptAllChangesOnSuccess, cancellationToken);
    }

    public override Task<int> SaveChangesAsync(CancellationToken cancellationToken = default)
        => SaveChangesAsync(acceptAllChangesOnSuccess: true, cancellationToken);

    private void PrepareChanges()
    {
        // Append-only audit trail (FR-ADM-153): audit rows are never modified or deleted.
        foreach (var entry in ChangeTracker.Entries<AuditEvent>())
        {
            if (entry.State is EntityState.Modified or EntityState.Deleted)
                throw new InvalidOperationException("Audit events are append-only and cannot be modified or deleted.");
        }

        // Denormalized display name kept in sync whenever employee names change.
        foreach (var entry in ChangeTracker.Entries<Employee>())
        {
            if (entry.State is not (EntityState.Added or EntityState.Modified)) continue;
            var employee = entry.Entity;
            var displayName = $"{employee.FirstName} {employee.LastName}".Trim();
            if (!string.Equals(employee.DisplayName, displayName, StringComparison.Ordinal))
                employee.DisplayName = displayName;
        }
    }
}
